let item = pull();
while (item) {
  state.count = (state.count || 0) + 1;
  state.totalDeposit = (state.totalDeposit || 0) + (item.payload.deposit || 0);
  state.totalPriority = (state.totalPriority || 0) + (item.payload.priority || 0);
  state.avgPriority = Number((state.totalPriority / state.count).toFixed(2));
  state.lastVIP = item.payload.accType === 'VIP' ? 'Yes' : (state.lastVIP || 'No');
  item = pull();
}
